def merge_sorted(a: List[int], b: List[int]) -> List[int]:
    merged = []
    i, j = 0, 0

    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            merged.append(a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    # Append remaining elements from a
    while i < len(a):
        merged.append(a[i])
        i += 1

    # Append remaining elements from b
    while j < len(b):
        merged.append(b[j])
        j += 1

    return merged

