def is_subset_list(a: List, b: List) -> bool:
    # If a is empty, it is trivially a subset of any list
    if not a:
        return True

    # Convert both lists to sets to remove duplicates and allow for O(1) lookups
    set_a = set(a)
    set_b = set(b)

    # Check if all elements of set_a are in set_b
    return set_a.issubset(set_b)

