def count_subsequence_matches(text: str, sub: str) -> int:
    def backtrack(index, sub_index):
        if sub_index == len(sub):
            return 1
        if index == len(text):
            return 0

        # If the current character in text matches the current character in sub
        if text[index] == sub[sub_index]:
            # Include the current character and move to the next character in sub
            return backtrack(index + 1, sub_index + 1) + backtrack(index + 1, sub_index)
        else:
            # Exclude the current character and move to the next character in text
            return backtrack(index + 1, sub_index)

    return backtrack(0, 0)
