from collections import *

def count_subsequence_matches(text: str, sub: str) -> int:
    # Initialize a DP table where dp[i][j] represents the number of ways to form sub[:j] using text[:i]
    dp = [[0] * (len(sub) + 1) for _ in range(len(text) + 1)]

    # Base case: there's one way to form an empty subsequence (by choosing no characters)
    for i in range(len(text) + 1):
        dp[i][0] = 1

    # Fill the DP table
    for i in range(1, len(text) + 1):
        for j in range(1, len(sub) + 1):
            if text[i - 1] == sub[j - 1]:
                # If the current characters match, we can either include the current character in the subsequence or exclude it
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1]
            else:
                # If the current characters don't match, we can only exclude the current character
                dp[i][j] = dp[i - 1][j]

    # The answer is the number of ways to form the entire subsequence using all characters in text
    return dp[len(text)][len(sub)]

