import subprocess

def is_host_reachable(host: str) -> bool:
    try:
        # Run the ping command with -c 1 option
        result = subprocess.run(['ping', '-c', '1', host], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        # If the command exits with status 0, the host is reachable
        return True
    except subprocess.CalledProcessError:
        # If the command exits with a non-zero status, the host is not reachable
        return False

