def parse_kv_pairs(text: str) -> dict[str, str]:
    if not text:
        return {}

    # Split the text by semicolons to get individual key-value pairs
    pairs = text.split(';')

    # Initialize an empty dictionary to store the parsed key-value pairs
    result = {}

    for pair in pairs:
        # Strip whitespace from the pair
        pair = pair.strip()

        # Check if the pair contains an '=' character
        if '=' in pair:
            # Split the pair into key and value using '=' as the delimiter
            key, value = pair.split('=', 1)

            # Strip whitespace from the key and value
            key = key.strip()
            value = value.strip()

            # Add the key-value pair to the result dictionary
            result[key] = value

    return result

