def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # Initialize two arrays to store the longest increasing subsequence ending at each index
    lis = [1] * n
    lds = [1] * n

    # Fill lis array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
