import subprocess

def make_tar(directory: str, archive_path: str) -> str:
    # Ensure the directory exists
    if not os.path.isdir(directory):
        raise ValueError(f"The directory '{directory}' does not exist.")

    # Ensure the archive path is not inside the directory
    if archive_path.startswith(directory + '/'):
        raise ValueError(f"The archive path '{archive_path}' must not be inside the directory '{directory}'.")

    # Create the tar archive using the system's tar command
    try:
