def longest_bitonic_length(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)

    # Initialize arrays to store the longest increasing subsequence ending at each index
    lis = [1] * n
    # Initialize arrays to store the longest decreasing subsequence starting at each index
    lds = [1] * n

