from typing import List

def matrix_power_mod(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
    def multiply_matrices(a: List[List[int]], b: List[List[int]], m: int) -> List[List[int]]:
        n = len(a)
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                for k in range(n):
                    result[i][j] = (result[i][j] + a[i][k] * b[k][j]) % m
        return result

    def matrix_power(matrix: List[List[int]], exp: int, mod: int) -> List[List[int]]:
        if exp == 0:
            return [[1 if i == j else 0 for j in range(len(matrix))] for i in range(len(matrix))]
        elif exp % 2 == 0:
            half_power = matrix_power(matrix, exp // 2, mod)
            return multiply_matrices(half_power, half_power, mod)
        else:
            half_power = matrix_power(matrix, (exp - 1) // 2, mod)
            return multiply_matrices(multiply_matrices(half_power, half_power, mod), matrix, mod)

    n = len(matrix)
    result = matrix_power(matrix, exp, mod)
    for i in range(n):
        for j in range(n):
            result[i][j] %= mod
    return result
