from typing import List, Tuple

def count_queens(n: int, blocked: List[Tuple[int, int]]) -> int:
    def is_valid_position(row: int, col: int) -> bool:
        for r, c in blocked:
            if r == row or c == col or abs(r - row) == abs(c - col):
                return False
        return True

    def backtrack(row: int) -> int:
        if row == n:
            return 1
        count = 0
        for col in range(n):
            if is_valid_position(row, col):
                blocked.append((row, col))
                count += backtrack(row + 1)
                blocked.pop()
        return count

    blocked = [(r, c) for r, c in blocked if 0 <= r < n and 0 <= c < n]
    return backtrack(0)
