from collections import deque

def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find starting and ending positions
    start, end = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize BFS queue and visited set
    queue = deque([(start, 0)])  # (position, moves)
    visited = set([start])

    while queue:
        pos, moves = queue.popleft()

        # Check if we reached the end
        if pos == end:
            return moves

        # Explore neighbors
        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy

            # Check bounds and unvisited cells
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != '#' and (nx, ny) not in visited:
                # If we encounter a wall, mark the cell as visited without adding to the queue
                if grid[nx][ny] == '.':
                    visited.add((nx, ny))
                else:
                    # If we encounter another 'S', we can break the wall
                    if grid[nx][ny] == 'S':
                        visited.add((nx, ny))
                        queue.append(((nx, ny), moves + 1))
                    else:
                        # Otherwise, continue exploring
                        visited.add((nx, ny))
                        queue.append(((nx, ny), moves + 1))

    # If no path is found, return -1
    return -1
