    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    if start is None or end is None:
        return -1

    # Initialize the queue for BFS and visited set
    queue = deque([(start, 0, False)])  # (position, steps, has_broken)
    visited = set()

    while queue:
        pos, steps, has_broken = queue.popleft()

        # Check if we reached the end
        if pos == end:
            return steps

        # Mark the current position as visited
        visited.add(pos)

        # Explore all four directions
        for dx, dy in directions:
            nx, ny = pos[0] + dx, pos[1] + dy

            # Check if the new position is within bounds
            if 0 <= nx < rows and 0 <= ny < cols:
                # If the cell is a wall and we haven't broken yet, break the wall
                if grid[nx][ny] == '#' and not has_broken:
                    queue.append(((nx, ny), steps + 1, True))
                # If the cell is empty or a wall and we have already broken, continue
                elif grid[nx][ny] != '#':
                    queue.append(((nx, ny), steps + 1, has_broken))

    # If no path is found, return -1
    return -1
