from typing import List

def shortest_path_one_break(grid: List[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def bfs(start_x, start_y):
        queue = [(start_x, start_y, 0, False)]  # (x, y, steps, has_broken)
        visited = set()

        while queue:
            x, y, steps, has_broken = queue.pop(0)

            if (x, y) == (rows - 1, cols - 1):
                return steps

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if is_valid(nx, ny):
                    if grid[nx][ny] == 'E':
                        return steps + 1

                    if grid[nx][ny] == '.' and (nx, ny, has_broken) not in visited:
                        visited.add((nx, ny, has_broken))
                        queue.append((nx, ny, steps + 1, has_broken))

                    if grid[nx][ny] == '#' and not has_broken:
                        visited.add((nx, ny, True))
                        queue.append((nx, ny, steps + 1, True))

        return -1

    start_x, start_y = None, None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
                break

    if start_x is None or start_y is None:
        return -1

    return bfs(start_x, start_y)
