    pattern = r'^\s*(-?\d+(\.\d+)?)\s*(\+\s*(-?\d+(\.\d+)?)|\-\s*(-?\d+(\.\d+)?)|\*\s*(-?\d+(\.\d+)?)|\/\s*(-?\d+(\.\d+)?)|\*\*\s*(-?\d+(\.\d+)?)|\(\s*(-?\d+(\.\d+)?)\s*\))\s*$'

    if not re.match(pattern, expression):
        raise ValueError("Invalid expression format")

    def parse_expression(expr: str) -> float:
        stack = []
        current_number = ""
        operator = None

        for char in expr:
            if char.isdigit() or char == '.':
                current_number += char
            elif char in "+-*/**()":
                if current_number:
                    stack.append(float(current_number))
                    current_number = ""
                if operator:
                    raise ValueError("Invalid expression format")
                operator = char
            elif char == " ":
                continue
            else:
                raise ValueError("Invalid character in expression")

        if current_number:
            stack.append(float(current_number))

        while stack:
            if operator == "+":
                stack[-2] += stack.pop()
            elif operator == "-":
                stack[-2] -= stack.pop()
            elif operator == "*":
                stack[-2] *= stack.pop()
            elif operator == "/":
                if stack[-1] == 0:
                    raise ZeroDivisionError("Division by zero")
                stack[-2] /= stack.pop()
            elif operator == "**":
