import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match the expression
    pattern = r'^\s*(-?\d+(\.\d+)?)\s*(\+\s*(-?\d+(\.\d+)?)\s*)*'

    # Check if the expression matches the pattern
    if not re.match(pattern, expression):
        raise ValueError("Invalid expression format")

    # Split the expression into components
    parts = expression.split()

    # Initialize the stack for operations
    stack = []

    # Iterate over the parts of the expression
    i = 0
    while i < len(parts):
        part = parts[i]

        # Handle numbers
        if part.isdigit() or (part.startswith('-') and part[1:].isdigit()):
            stack.append(float(part))

        # Handle unary minus
        elif part == '-':
            if i + 1 < len(parts) and (parts[i + 1].isdigit() or (parts[i + 1].startswith('-') and parts[i + 1][1:].isdigit())):
                stack.append(-float(parts[i + 1]))
                i += 1
            else:
                raise ValueError("Invalid expression format")

        # Handle binary operators
        elif part in ('+', '-', '*', '/', '**'):
            # Pop operands from the stack
            right = stack.pop()
            left = stack.pop()

            # Perform the operation
            if part == '+':
                stack.append(left + right)
            elif part == '-':
                stack.append(left - right)
            elif part == '*':
                stack.append(left * right)
            elif part == '/':
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                stack.append(left / right)
            elif part == '**':
                stack.append(left ** right)

        # Skip spaces
        elif part == '':
            continue

        else:
            raise ValueError("Invalid expression format")

        i += 1

    # The final result should be the only element left in the stack
    if len(stack) != 1:
        raise ValueError("Invalid expression format")

    return stack[0]
