            stack.append(float(part))
        elif part in '+-*/**':
            # Handle unary minus
            if part == '-':
                if not stack:
                    raise ValueError("Invalid expression")
                stack[-1] = -stack[-1]
            else:
                # Handle binary operations
                if len(stack) < 2:
                    raise ValueError("Invalid expression")
