import re

def evaluate_expression(expression: str) -> float:
    # Regular expression to match valid tokens in the expression
    token_pattern = re.compile(r'\d+\.\d+|\d+|\+|-|\*|/|\^|\(|\)|\s')

    # Tokenize the expression
    tokens = token_pattern.findall(expression)

    # Stack for operators
    operator_stack = []

    # Stack for operands
    operand_stack = []

    # Precedence of operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}

    # Associativity of operators
    associativity = {'+': 'left', '-': 'left', '*': 'left', '/': 'left', '^': 'right'}

    def apply_operator(op, b, a):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            if b == 0:
                raise ZeroDivisionError("Division by zero")
            return a / b
        elif op == '^':
            return a ** b

    for token in tokens:
        if token.isdigit() or '.' in token:
            # Push operand onto stack
            operand_stack.append(float(token))
        elif token in precedence:
            # Apply operators from stack to operand stack
            while (operator_stack and operator_stack[-1] != '(' and
                   (associativity[token] == 'left' and precedence[token] <= precedence[operator_stack[-1]] or
                    associativity[token] == 'right' and precedence[token] < precedence[operator_stack[-1]])):
                b = operand_stack.pop()
                a = operand_stack.pop()
                op = operator_stack.pop()
                result = apply_operator(op, b, a)
                operand_stack.append(result)
            operator_stack.append(token)
        elif token == '(':
            operator_stack.append(token)
        elif token == ')':
            while operator_stack and operator_stack[-1] != '(':
                b = operand_stack.pop()
                a = operand_stack.pop()
                op = operator_stack.pop()
                result = apply_operator(op, b, a)
                operand_stack.append(result)
            if operator_stack and operator_stack[-1] == '(':
                operator_stack.pop()
            else:
                raise ValueError("Mismatched parentheses")

    # Apply remaining operators
    while operator_stack:
        b = operand_stack.pop()
        a = operand_stack.pop()
        op = operator_stack.pop()
        result = apply_operator(op, b, a)
        operand_stack.append(result)

    # Check if there is exactly one operand left
    if len(operand_stack) != 1:
        raise ValueError("Invalid expression")

    return operand_stack[0]

