def stabilize_sandpile(grid: list[list[int]]) -> list[list[int]]:
    if not grid:
        return []

    def topple(grid, r, c):
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]):
            return
        if grid[r][c] < 4:
            return

        # Topple the current cell
        grid[r][c] -= 4
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            grid[nr][nc] += 1

    while True:
        stable = True
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] >= 4:
                    stable = False
                    topple(grid, r, c)
        if stable:
            break

    return grid
