from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    L = reduce(lcm, [m for _, m in congruences])
    solutions = []

    for r, m in congruences:
        # Normalize r modulo L
        r %= L
        # Find the smallest k such that r + km is divisible by m
        k = (m - r % m) % m
        # Add the solution to the list
        solutions.append((r + k * L, L))

    # Check if all solutions are the same
    if len(set(solutions)) == 1:
        return solutions[0]
    else:
        return None
