from collections import defaultdict

def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    # Build the adjacency list representation of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize the distance array and the queue for BFS
    distances = [float('inf')] * n
    distances[source] = 0
    queue = [source]

    # Perform BFS to find the shortest path
    while queue:
        current = queue.pop(0)
        for neighbor in graph[current]:
            if distances[neighbor] > distances[current] + 1:
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)

    # Check if the target is reachable
    if distances[target] == float('inf'):
        return 0

    # Count the number of distinct shortest paths
    def count_paths(node):
        if node == target:
            return 1
        count = 0
        for neighbor in graph[node]:
            if distances[neighbor] == distances[node] - 1:
                count += count_paths(neighbor)
        return count

    return count_paths(source)
