def weighted_edit_cost(source: str, target: str, insert_cost: int, delete_cost: int, replace_cost: int) -> int:
    m, n = len(source), len(target)

    # Initialize a 2D array to store the edit costs
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array
    for i in range(1, m + 1):
        dp[i][0] = i * delete_cost  # Cost to delete all characters in source
    for j in range(1, n + 1):
        dp[0][j] = j * insert_cost  # Cost to insert all characters in target

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                cost = 0
            else:
                cost = replace_cost
            dp[i][j] = min(dp[i - 1][j] + delete_cost,  # Delete from source
                           dp[i][j - 1] + insert_cost,  # Insert into target
                           dp[i - 1][j - 1] + cost)  # Replace or match

    return dp[m][n]
