from math import gcd
from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    L = reduce(lcm, [m for _, m in congruences])
    solutions = []

    for r, m in congruences:
        # Find the smallest positive solution for each congruence
        k = (r % m + m) % m  # Adjust r to be non-negative modulo m
        solutions.append((k, m))

    # Check if there is a common solution
    for i, (r1, m1) in enumerate(solutions):
        for j, (r2, m2) in enumerate(solutions):
            if i != j and r1 % m2 != r2 % m1:
                return None

    # Calculate the unique solution
    x = sum(r * pow(m, -1, L) * m for r, m in solutions) % L
    return (x, L)

# Example usage:
# print(solve_congruences([(3, 5), (2, 7)]))  # Output: (2, 35)
# print(solve_congruences([(1, 4), (2, 6)]))  # Output: None
