from functools import reduce

def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    if not congruences:
        return (0, 1)

    def lcm(a, b):
        return abs(a * b) // gcd(a, b)

    L = reduce(lcm, [m for _, m in congruences])
    solutions = []

    for r, m in congruences:
        # Normalize r to be within the range [0, m-1]
        r %= m
        # Find the smallest positive solution for each congruence
        x = r
        while x < 0:
            x += m
        solutions.append(x)

    # Check if there is a common solution
    for i in range(len(solutions)):
        for j in range(i + 1, len(solutions)):
            if solutions[i] != solutions[j]:
                return None

    return (solutions[0], L)
