    if not (2 <= from_base <= 36) or not (2 <= to_base <= 36):
        raise ValueError("Bases must be between 2 and 36.")

    if not number:
        return "0"

    if number[0] == '-':
        is_negative = True
        number = number[1:]
    else:
        is_negative = False

    if not all(c.isalnum() and c.lower() in '0123456789abcdefghijklmnopqrstuvwxyz' for c in number):
        raise ValueError("Invalid characters in input number.")

    # Convert from base to decimal
    decimal_value = 0
    for i, digit in enumerate(reversed(number)):
        value = ord(digit.lower()) - ord('0')
        if value >= from_base:
            raise ValueError(f"Digit {digit} is not valid in base {from_base}.")
        decimal_value += value * (from_base ** i)

    # Convert from decimal to target base
    if decimal_value == 0:
        return "0"

    result = ""
    while decimal_value > 0:
        remainder = decimal_value % to_base
        result = chr(ord('0') + remainder) + result
        decimal_value //= to_base

    if is_negative:
        result = '-' + result

    return result
