def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    # Sort jobs by profit in descending order, then by original order
    jobs.sort(key=lambda x: (-x[1], jobs.index(x)))

    # Initialize a dictionary to keep track of available slots
    slots = {i: None for i in range(1, max(job[1] for job in jobs) + 1)}

    # Schedule jobs
    scheduled_jobs = []
    for name, deadline, profit in jobs:
        for slot in range(deadline, 0, -1):
            if slots[slot] is None:
                slots[slot] = name
                scheduled_jobs.append(name)
                break

    return scheduled_jobs

