def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    # Convert the start date string to a datetime object
    start_date = datetime.strptime(start, "%Y-%m-%d")

    # Define a helper function to check if a date is a business day
    def is_business_day(date):
        return date.weekday() < 5 and date.strftime("%Y-%m-%d") not in holidays

    # Adjust the start date based on the number of business days to add or subtract
    for _ in range(abs(n)):
        if n > 0:
            # Move forward until a business day is found
            while not is_business_day(start_date):
                start_date += timedelta(days=1)
        else:
            # Move backward until a business day is found
            while not is_business_day(start_date):
                start_date -= timedelta(days=1)

    # Return the resulting date as a string
    return start_date.strftime("%Y-%m-%d")

