            values.append(abs(right))
        elif operator == 'sin':
            values.append(math.sin(right))
        elif operator == 'cos':
            values.append(math.cos(right))

    def infix_to_postfix(tokens):
        operators = []
        postfix = []
        for token in tokens:
            if isinstance(token, float):
                postfix.append(token)
            elif token in '+-*/**':
                while (operators and operators[-1] != '(' and
                       ((token == '*' or token == '/') and
                        (operators[-1] == '*' or operators[-1] == '/'))):
                    apply_operator(operators, postfix)
                operators.append(token)
            elif token in 'sqrt abs sin cos':
                while (operators and operators[-1] != '(' and
