def matches_filter(expression: str, record: dict) -> bool:
    # Parse the expression using ast.literal_eval to safely evaluate it
    try:
        parsed_expr = ast.parse(expression, mode='eval').body
    except (SyntaxError, ValueError):
        raise ValueError("Invalid expression format")

    # Define a visitor class to handle the evaluation of the parsed expression
    class ExpressionEvaluator(ast.NodeVisitor):
        def visit_Name(self, node):
            if node.id not in record:
                raise ValueError(f"Key '{node.id}' not found in record")
            return record[node.id]

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.Eq):
                return left == right
            elif isinstance(node.op, ast.NotEq):
                return left != right
            elif isinstance(node.op, ast.Lt):
                return left < right
            elif isinstance(node.op, ast.LtE):
                return left <= right
            elif isinstance(node.op, ast.Gt):
                return left > right
            elif isinstance(node.op, ast.GtE):
                return left >= right
            elif isinstance(node.op, ast.And):
                return self.visit(node.left) and self.visit(node.right)
            elif isinstance(node.op, ast.Or):
                return self.visit(node.left) or self.visit(node.right)
            else:
                raise ValueError(f"Unsupported operator: {node.op}")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator: {node.op}")

    # Evaluate the parsed expression
    evaluator = ExpressionEvaluator()
    return evaluator.visit(parsed_expr)

