            operator = operators.pop()
            value = values.pop()
            if operator == '-':
                values.append(-value)

        def apply_function(operators, values, func):
            value = values.pop()
            values.append(func(value))

        def tokenize(s):
            i = 0
            while i < len(s):
                if s[i].isspace():
                    i += 1
                    continue
                if s[i] in '0123456789.+-*/()':
