from collections import OrderedDict

def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []
    keys = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]  # Remove existing key to make room
            elif len(cache) >= capacity:
                cache.popitem(last=False)  # Remove least recently used item
            cache[key] = value  # Add new key-value pair
            keys.append(key)
        elif op == "get":
            if key in cache:
                results.append(cache[key])
                keys.remove(key)  # Mark as most recently used
                keys.append(key)
            else:
                results.append(None)

    return results, keys
