import re

def parse_csv(text: str) -> list[list[str]]:
    def parse_field(field):
        if field.startswith('"'):
            # Handle quoted field
            result = []
            i = 1
            while i < len(field) - 1:
                if field[i] == '"':
                    if i + 1 < len(field) and field[i + 1] == '"':
                        result.append('"')
                        i += 2
                    else:
                        break
                else:
                    result.append(field[i])
                i += 1
            return ''.join(result)
        else:
            # Handle unquoted field
            return field.strip()

    lines = text.split('\n')
    records = []
    for line in lines:
        fields = re.split(r',(?=(?:[^"]*"[^"]*")*[^"]*$)', line)
        parsed_fields = [parse_field(field) for field in fields]
        records.append(parsed_fields)

    return records
