import ast

def matches_filter(expression: str, record: dict) -> bool:
    # Define a custom visitor to evaluate the AST
    class FilterEvaluator(ast.NodeVisitor):
        def visit_Name(self, node):
            if node.id in record:
                return record[node.id]
            else:
                raise ValueError(f"Unknown variable '{node.id}'")

        def visit_BinOp(self, node):
            left = self.visit(node.left)
            right = self.visit(node.right)
            if isinstance(node.op, ast.Add):
                return left + right
            elif isinstance(node.op, ast.Sub):
                return left - right
            elif isinstance(node.op, ast.Mult):
                return left * right
            elif isinstance(node.op, ast.Div):
                return left / right
            elif isinstance(node.op, ast.FloorDiv):
                return left // right
            elif isinstance(node.op, ast.Mod):
                return left % right
            elif isinstance(node.op, ast.Pow):
                return left ** right
            elif isinstance(node.op, ast.Eq):
                return left == right
            elif isinstance(node.op, ast.NotEq):
                return left != right
            elif isinstance(node.op, ast.Lt):
                return left < right
            elif isinstance(node.op, ast.LtE):
                return left <= right
            elif isinstance(node.op, ast.Gt):
                return left > right
            elif isinstance(node.op, ast.GtE):
                return left >= right
            elif isinstance(node.op, ast.And):
                return left and right
            elif isinstance(node.op, ast.Or):
                return left or right
            elif isinstance(node.op, ast.Not):
                return not left
            else:
                raise ValueError(f"Unsupported operator '{node.op.__class__.__name__}'")

        def visit_UnaryOp(self, node):
            operand = self.visit(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            elif isinstance(node.op, ast.UAdd):
                return operand
            elif isinstance(node.op, ast.Not):
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator '{node.op.__class__.__name__}'")

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

    # Parse the expression into an AST
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        raise ValueError("Invalid expression")

    # Evaluate the AST
    evaluator = FilterEvaluator()
    return evaluator.visit(tree)

# Example usage:
