    # Define a custom visitor to handle the evaluation of the expression
    class FilterEvaluator(ast.NodeVisitor):
        def __init__(self, record):
            self.record = record

        def visit_Name(self, node):
            if node.id in self.record:
                return self.record[node.id]
            else:
                raise ValueError(f"Key '{node.id}' not found in record")

        def visit_Num(self, node):
            return node.n

        def visit_Str(self, node):
            return node.s

