                raise ValueError(f"Unsupported operator: {op}")
        elif isinstance(node, ast.UnaryOp):
            operand = evaluate(node.operand)
            op = node.op.__class__.__name__
            if op == 'Invert':
                return ~operand
            elif op == 'Not':
                return not operand
            else:
                raise ValueError(f"Unsupported unary operator: {op}")
        elif isinstance(node, ast.Compare):
            left = evaluate(node.left)
            ops = [op.__class__.__name__ for op in node.ops]
            comparands = [evaluate(comp) for comp in node.comparators]
            for op, comp in zip(ops, comparands):
                if op == 'Lt':
                    if left < comp:
                        continue
                    else:
                        return False
                elif op == 'LtE':
                    if left <= comp:
                        continue
                    else:
                        return False
                elif op == 'Gt':
                    if left > comp:
                        continue
                    else:
                        return False
                elif op == 'GtE':
                    if left >= comp:
                        continue
                    else:
                        return False
                elif op == 'Eq':
                    if left == comp:
                        continue
                    else:
                        return False
                elif op == 'Ne':
                    if left != comp:
                        continue
                    else:
                        return False
                else:
                    raise ValueError(f"Unsupported comparison operator: {op}")
            return True
        elif isinstance(node, ast.BoolOp):
            values = [evaluate(value) for value in node.values]
            op = node.op.__class__.__name__
            if op == 'And':
                return all(values)
            elif op == 'Or':
                return any(values)
            else:
                raise ValueError(f"Unsupported boolean operator: {op}")
        elif isinstance(node, ast.Name):
            if node.id not in record:
                raise ValueError(f"Unknown variable: {node.id}")
            return record[node.id]
        else:
            raise ValueError(f"Unsupported node type: {type(node).__name__}")

    try:
        tree = ast.parse(expression, mode='eval')
        return evaluate(tree.body)
    except (SyntaxError, ValueError) as e:
        raise ValueError(f"Invalid expression: {e}")

