    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for ring in range(n // 2):
        start_row, end_row = ring, n - ring - 1
        start_col, end_col = ring, n - ring - 1

        # Collect elements of the current ring
        elements = []
        for i in range(start_row, end_row + 1):
            elements.append(matrix[i][start_col])
        for j in range(start_col + 1, end_col + 1):
            elements.append(matrix[end_row][j])
        for i in range(end_row - 1, start_row - 1, -1):
            elements.append(matrix[i][end_col])
        for j in range(end_col - 1, start_col, -1):
            elements.append(matrix[start_row][j])

        # Rotate the collected elements
        k %= len(elements)
        if k:
            elements = elements[-k:] + elements[:-k]

        # Place the rotated elements back into the current ring
        index = 0
        for i in range(start_row, end_row + 1):
            result[i][start_col] = elements[index]
