def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = OrderedDict()
    results = []
    keys = []

    for op, key, value in operations:
        if op == "put":
            if key in cache:
                del cache[key]
            cache[key] = value
            keys.append(key)
            if len(cache) > capacity:
                keys.pop(0)
        elif op == "get":
            if key in cache:
                results.append(cache[key])
                keys.remove(key)
                keys.append(key)
            else:
                results.append(None)

    return results, keys
