import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse the IP address using ipaddress
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is public
        if ip.is_global:
            return True

        # Check if the IP is in the shared address space 100.64.0.0/10
        if ip.version == 4 and ip >= ipaddress.IPv4Address('100.64.0.0') and ip < ipaddress.IPv4Address('100.65.0.0'):
            return False

        # Check if the IP is an IPv4 broadcast address
        if ip.version == 4 and ip.is_broadcast:
            return False

        # Check if the IP is a mapped IPv6 address
        if ip.version == 6 and ip.exploded.startswith('::ffff:'):
            inner_ipv4 = ip.exploded.split(':')[-1]
            inner_ip = ipaddress.IPv4Address(inner_ipv4)
            return is_public_ip(str(inner_ip))

        return False

    except ValueError:
        # If parsing fails, the IP is not in standard text form
        return False
