import ipaddress

def is_public_ip(ip_str: str) -> bool:
    try:
        # Try to parse the IP address using ipaddress
        ip = ipaddress.ip_address(ip_str)

        # Check if the IP is public
        if ip.is_global:
            return True

        # Check for specific non-public ranges
        if ip.is_private:
            return False
        if ip.is_loopback:
            return False
        if ip.is_link_local:
            return False
        if ip.is_multicast:
            return False
        if ip.is_unspecified:
            return False
        if ip.is_reserved:
            return False
        if ip.is_documentation:
            return False
        if ip.is_shared:
            return False

        # Check for IPv4-mapped IPv6 addresses
        if isinstance(ip, ipaddress.IPv6Address):
            inner_ipv4 = ip.ipv4_mapped
            if inner_ipv4.is_private:
                return False
            if inner_ipv4.is_loopback:
                return False
            if inner_ipv4.is_link_local:
                return False
            if inner_ipv4.is_multicast:
                return False
            if inner_ipv4.is_unspecified:
                return False
            if inner_ipv4.is_reserved:
                return False
            if inner_ipv4.is_documentation:
                return False
            if inner_ipv4.is_shared:
                return False

        return True

    except ValueError:
        # If parsing fails, the IP is not in standard text form
        return False
