import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with https://
    if not url.startswith("https://"):
        return False

    # Check for backslashes, spaces, or control characters
    if any(char in url for char in "\\\s\x00-\x1f"):
        return False

    # Split the URL into scheme, netloc, and path
    parts = url.split("//")
    if len(parts) != 2:
        return False

    netloc = parts[1]

    # Check if the netloc contains a colon
    if ":" in netloc:
        user_info, host_port = netloc.split(":", 1)
    else:
        user_info = ""
        host_port = netloc

    # Check if the host part ends with a dot
    if not host_port.endswith("."):
        return False

    # Remove the final dot from the host
    host = host_port[:-1]

    # Check if the host is a valid DNS name
    if not re.match(r"^[a-zA-Z][a-zA-Z0-9-]*\.[a-zA-Z]+$", host):
        return False

    # Check if the host is not localhost or ends with .localhost
    if host.lower() == "localhost" or host.lower().endswith(".localhost"):
        return False

    # Check if the port is missing or is 443
    if ":" in host_port:
        port = int(host_port.split(":")[1])
        if port != 443:
            return False

    return True

