import re

def evaluate_expression(expr: str) -> int:
    # Remove spaces from the expression
    expr = expr.replace(" ", "")

    # Define a helper function to evaluate a sub-expression
    def evaluate_sub_expr(expr: str) -> int:
        stack = []
        current_num = ""
        operator = "+"

        for char in expr:
            if char.isdigit():
                current_num += char
            elif char == "(":
                stack.append((operator, current_num))
                operator = "+"
                current_num = ""
            elif char in "+-*/^":
                if operator == "^":
                    while stack and stack[-1][0] == "^":
                        op, num = stack.pop()
                        current_num = str(int(current_num) ** int(num))
                    stack.append((operator, current_num))
                    operator = char
                    current_num = ""
                else:
                    while stack and (stack[-1][0] == "*" or stack[-1][0] == "/" or stack[-1][0] == "^"):
                        op, num = stack.pop()
                        if op == "*":
                            current_num = str(int(current_num) * int(num))
                        elif op == "/":
                            if num == "0":
                                raise ZeroDivisionError("Division by zero")
                            current_num = str(int(current_num) // int(num))
                        elif op == "^":
                            current_num = str(int(current_num) ** int(num))
                    stack.append((operator, current_num))
                    operator = char
                    current_num = ""
            elif char == ")":
                while stack and stack[-1][0] != "(":
                    op, num = stack.pop()
                    if op == "*":
                        current_num = str(int(current_num) * int(num))
                    elif op == "/":
                        if num == "0":
                            raise ZeroDivisionError("Division by zero")
                        current_num = str(int(current_num) // int(num))
                    elif op == "^":
                        current_num = str(int(current_num) ** int(num))
                stack.pop()  # Pop the "("
                if operator == "+":
                    current_num = str(int(stack.pop()[1]) + int(current_num))
                elif operator == "-":
                    current_num = str(int(stack.pop()[1]) - int(current_num))
                elif operator == "*":
                    current_num = str(int(stack.pop()[1]) * int(current_num))
                elif operator == "/":
                    if current_num == "0":
                        raise ZeroDivisionError("Division by zero")
                    current_num = str(int(stack.pop()[1]) // int(current_num))
                elif operator == "^":
                    current_num = str(int(stack.pop()[1]) ** int(current_num))
                operator = "+"

        # Evaluate remaining numbers in the stack
        while stack:
            op, num = stack.pop()
            if op == "*":
                current_num = str(int(current_num) * int(num))
            elif op == "/":
                if num == "0":
                    raise ZeroDivisionError("Division by zero")
                current_num = str(int(current_num) // int(num))
            elif op == "^":
                current_num = str(int(current_num) ** int(num))

        return int(current_num)

    # Handle unary minus
    if expr.startswith("-"):
        expr = "0" + expr

    # Evaluate the entire expression
    return evaluate_sub_expr(expr)

