from typing import *
from collections import defaultdict

def process_orders(events: list[tuple[str, str, int]]) -> tuple[dict[str, int], list[tuple[str, int]]]:
    stock = defaultdict(int)
    waiting = []

    for kind, item, quantity in events:
        if kind == 'receive':
            stock[item] += quantity
        elif kind == 'order':
            if stock[item] >= quantity:
                stock[item] -= quantity
            else:
                waiting.append((item, quantity))

    # Fulfill waiting orders
    waiting.sort(key=lambda x: (x[1], events.index(x)))
    for item, quantity in waiting:
        if stock[item] >= quantity:
            stock[item] -= quantity
        else:
            waiting.remove((item, quantity))

    return dict(stock), waiting
