def run_stack_machine(program: list[str]) -> list[int]:
    stack = []
    ip = 0
    max_instructions = 1000

    while ip < len(program):
        instruction = program[ip]
        parts = instruction.split()

        if len(parts) != 2:
            raise ValueError(f"Invalid instruction: {instruction}")

        op = parts[0]
        arg = int(parts[1])

        if op == "PUSH":
            stack.append(arg)
        elif op == "POP":
            if not stack:
                raise ValueError("POP on empty stack")
            stack.pop()
        elif op == "DUP":
            if not stack:
                raise ValueError("DUP on empty stack")
            stack.append(stack[-1])
        elif op == "SWAP":
            if len(stack) < 2:
                raise ValueError("SWAP requires at least two elements on stack")
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == "ADD":
            if len(stack) < 2:
                raise ValueError("ADD requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a + b)
        elif op == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a - b)
        elif op == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL requires at least two elements on stack")
            a, b = stack.pop(), stack.pop()
            stack.append(a * b)
        elif op == "JMP":
            if ip + arg >= len(program):
                raise ValueError("JMP out of bounds")
            ip += arg
        elif op == "JZ":
            if len(stack) < 1:
                raise ValueError("JZ requires at least one element on stack")
            if stack.pop() == 0:
                if ip + arg >= len(program):
                    raise ValueError("JZ out of bounds")
                ip += arg
        elif op == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {op}")

        if max_instructions <= 0:
            raise RuntimeError("Too many instructions executed")

        max_instructions -= 1
        ip += 1

    return stack
