                raise ValueError("ADD requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a + b)
        elif parts[0] == "SUB":
            if len(stack) < 2:
                raise ValueError("SUB requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a - b)
        elif parts[0] == "MUL":
            if len(stack) < 2:
                raise ValueError("MUL requires at least two elements on the stack")
            a = stack.pop()
            b = stack.pop()
            stack.append(a * b)
        elif parts[0] == "JMP":
            try:
                ip = int(parts[1])
            except ValueError:
                raise ValueError(f"Invalid target for JMP: {parts[1]}")
        elif parts[0] == "JZ":
