            if stack.pop() == 0:
                try:
                    ip = int(parts[1])
                except ValueError:
                    raise ValueError(f"Invalid target for JZ: {parts[1]}")
        elif parts[0] == "HALT":
            break
        else:
            raise ValueError(f"Unknown instruction: {instruction}")

        ip += 1

    return stack
