                continue
            if op[2] <= 0:
                failed.append(i)
                continue
            final_balances[op[1]] += op[2]
        elif op[0] == 'withdraw':
            if op[1] not in final_balances:
                failed.append(i)
                continue
            if op[2] <= 0:
                failed.append(i)
                continue
            if final_balances[op[1]] < op[2]:
                failed.append(i)
                continue
            final_balances[op[1]] -= op[2]
        elif op[0] == 'transfer':
            if op[1] not in final_balances or op[2] not in final_balances:
                failed.append(i)
                continue
            if op[1] == op[2]:
                failed.append(i)
                continue
            if op[3] <= 0:
                failed.append(i)
                continue
            if final_balances[op[1]] < op[3] + 2:
                failed.append(i)
                continue
            final_balances[op[1]] -= op[3] + 2
            final_balances[op[2]] += op[3]
        elif op[0] == 'freeze':
            if op[1] not in final_balances:
                failed.append(i)
                continue
            final_balances[op[1]] |= 1 << 31  # Mark as frozen by setting the highest bit
        elif op[0] == 'unfreeze':
            if op[1] not in final_balances:
                failed.append(i)
                continue
            final_balances[op[1]] &= ~(1 << 31)  # Unmark as frozen by clearing the highest bit
        else:
            failed.append(i)
            continue

    return final_balances, failed
